function rowDigit(n: number, k: number): number {
  let row = "0";
  for (let i = 1; i < n; i++) {
    let next = "";
    for (const c of row) next += c === "0" ? "01" : "10";
    row = next;
  }
  return Number(row[k - 1]);
}

